package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.FineTuning.Jobs.Checkpoints.List(
		context.TODO(),
		"ft-AF1WoRqd3aJAHsqc9NY7iL8F",
		openai.FineTuningJobCheckpointListParams{
			After: param.NewOpt[string]("after"),
			Limit: param.NewOpt[int64](10),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
